1	// Page-load measurements against a running production build (`npm run build && npx next start -p 3101`).
2	// Per page and viewport it runs a few cold loads (fresh context, no HTTP cache) and reports the median TTFB, FCP, LCP,
3	// time until the page heading is visible, CLS, long tasks over 50 ms, transfer size and JS bytes.
4	//   node scripts/perf-pages.mjs <runs> <label=baseUrl>...      (needs e2e/.auth.json from scripts/e2e-auth.mjs)
5	// Several builds are measured interleaved, run by run, so machine noise hits them alike. Writes .qa/perf-<label>.json each.
6	import { mkdirSync, writeFileSync } from "node:fs";
7	import { chromium, devices } from "@playwright/test";
8	
9	const [runsArg, ...targetArgs] = process.argv.slice(2);
10	const targets = targetArgs.map(arg => { const [label, base] = [arg.slice(0, arg.indexOf("=")), arg.slice(arg.indexOf("=") + 1)]; return { label, base }; });
11	if (!targets.length || !targets.every(target => target.label && target.base)) throw new Error("usage: node scripts/perf-pages.mjs <runs> <label=baseUrl>...");
12	const runs = Number(runsArg);
13	const PAGES = ["/", "/ai", "/ai/artifacts", "/ai/activity", "/money/accounts", "/money/transactions", "/money/recurring", "/money/wealth", "/plan", "/plan/spending", "/settings"];
14	const VIEWPORTS = { desktop: { viewport: { width: 1440, height: 900 } }, mobile: { ...devices["Pixel 7"] } };
15	
16	// Runs in the page before anything else: LCP, CLS, long tasks and when a heading first shows.
17	const probe = () => {
18	  const m = (window.__perf = { lcp: 0, cls: 0, longTasks: 0, longTaskMs: 0, heading: 0 });
19	  new PerformanceObserver(list => { for (const e of list.getEntries()) m.lcp = e.startTime; }).observe({ type: "largest-contentful-paint", buffered: true });
20	  new PerformanceObserver(list => { for (const e of list.getEntries()) if (!e.hadRecentInput) m.cls += e.value; }).observe({ type: "layout-shift", buffered: true });
21	  new PerformanceObserver(list => { for (const e of list.getEntries()) { m.longTasks++; m.longTaskMs += e.duration; } }).observe({ type: "longtask", buffered: true });
22	  const tick = () => {
23	    const h = document.querySelector("main h1, h1");
24	    if (h && h.getBoundingClientRect().height > 0 && getComputedStyle(h).visibility !== "hidden") m.heading = performance.now(); else requestAnimationFrame(tick);
25	  };
26	  requestAnimationFrame(tick);
27	};
28	
29	const median = values => { const sorted = values.filter(v => v != null).sort((a, b) => a - b); return sorted.length ? sorted[Math.floor(sorted.length / 2)] : null; };
30	const browser = await chromium.launch();
31	const results = Object.fromEntries(targets.map(target => [target.label, {}]));
32	for (const [vpName, vp] of Object.entries(VIEWPORTS)) {
33	  for (const path of PAGES) {
34	    const samples = Object.fromEntries(targets.map(target => [target.label, []]));
35	    for (let run = -1; run < runs; run++) { // run -1 warms server caches and is not recorded
36	      for (const { label, base } of targets) {
37	        const context = await browser.newContext({ ...vp, baseURL: base, storageState: "e2e/.auth.json" });
38	        await context.addInitScript(probe);
39	        const page = await context.newPage();
40	        let transfer = 0, js = 0, requests = 0;
41	        page.on("requestfinished", async request => {
42	          try {
43	            const sizes = await request.sizes(); const bytes = sizes.responseBodySize + sizes.responseHeadersSize;
44	            transfer += bytes; requests++;
45	            if (request.resourceType() === "script") js += sizes.responseBodySize;
46	          } catch { /* request gone with the context */ }
47	        });
48	        const response = await page.goto(path, { waitUntil: "load" }).catch(() => null);
49	        await page.waitForTimeout(2000);
50	        const m = await page.evaluate(() => {
51	          const nav = performance.getEntriesByType("navigation")[0];
52	          const fcp = performance.getEntriesByName("first-contentful-paint")[0];
53	          return { ...window.__perf, ttfb: nav.responseStart, fcp: fcp?.startTime ?? null, load: nav.loadEventEnd };
54	        });
55	        if (run >= 0) samples[label].push({ ...m, status: response?.status(), final: new URL(page.url()).pathname, transferKB: transfer / 1024, jsKB: js / 1024, requests });
56	        await context.close();
57	      }
58	    }
59	    for (const { label } of targets) {
60	      const pick = key => median(samples[label].map(s => s[key]));
61	      const r = results[label][`${vpName} ${path}`] = { final: samples[label][0]?.final, status: samples[label][0]?.status, ttfb: pick("ttfb"), fcp: pick("fcp"), lcp: pick("lcp"), heading: pick("heading"), load: pick("load"),
62	        cls: pick("cls"), longTasks: pick("longTasks"), longTaskMs: pick("longTaskMs"), transferKB: pick("transferKB"), jsKB: pick("jsKB"), requests: pick("requests") };
63	      console.log(`${label.padEnd(8)} ${vpName.padEnd(7)} ${path.padEnd(22)} ttfb ${r.ttfb?.toFixed(0)} fcp ${r.fcp?.toFixed(0)} lcp ${r.lcp?.toFixed(0)} heading ${r.heading?.toFixed(0)} cls ${r.cls?.toFixed(3)} lt ${r.longTasks}/${r.longTaskMs?.toFixed(0)}ms xfer ${r.transferKB?.toFixed(0)}KB js ${r.jsKB?.toFixed(0)}KB ${r.final !== path ? `-> ${r.final}` : ""}`);
64	    }
65	  }
66	}
67	await browser.close();
68	mkdirSync(".qa", { recursive: true });
69	for (const { label } of targets) writeFileSync(`.qa/perf-${label}.json`, JSON.stringify(results[label], null, 2));
70

