65	      const last = text.trim().split("\n").pop();
66	      return { conversationId, tHeaders, tFirst, tFull: performance.now() - t0, status, result: last.slice(0, 120) };
67	    });
68	    if (run === -1) console.log("chat sample:", timing.status, timing.result);
69	    if (run >= 0) { headers.push(timing.tHeaders); first.push(timing.tFirst); full.push(timing.tFull); conversationId = timing.conversationId; }
70	  }
