import postgres from "postgres"; import {createClient} from "@supabase/supabase-js"; import {randomUUID,randomBytes} from "node:crypto";
const admin=createClient(process.env.NEXT_PUBLIC_SUPABASE_URL,process.env.SUPABASE_SERVICE_ROLE_KEY,{auth:{persistSession:false}});
const db=postgres(process.env.SUPABASE_DB_URL,{max:1,onnotice(){}});
const c=await admin.auth.admin.createUser({email:`qa-delprobe-${randomUUID()}@example.invalid`,password:randomBytes(24).toString('hex'),email_confirm:true,user_metadata:{qa_test:'delprobe'}});
console.log('create',c.error?.message??'ok');
if(c.data.user){const u=c.data.user.id;
 const d=await admin.auth.admin.deleteUser(u);console.log('delete fresh',d.error?.message??'ok');
 console.log('left',(await db`select count(*)::int n from auth.users where id=${u}`)[0].n,(await db`select count(*)::int n from public.workspaces where owner_id=${u}`)[0].n);}
// leftover disposable users: what refs block them
const left=await db`select u.id,u.email,u.created_at,u.raw_user_meta_data->>'qa_test' qa,(select count(*)::int from public.workspaces w where w.owner_id=u.id) ws from auth.users u where u.email like '%example.invalid' or u.email like '%example.test' order by created_at desc`;
const by={};left.forEach(r=>{const k=(r.qa||'none')+' ws='+r.ws;by[k]=(by[k]||0)+1});console.log(by);console.log('newest',left[0]?.created_at,'oldest',left.at(-1)?.created_at);
const noWs=left.find(r=>r.ws===0&&r.qa!=='e2e-auth');
if(noWs){console.log('try delete no-ws user');const d=await admin.auth.admin.deleteUser(noWs.id);console.log(d.error?.message??'deleted');
 if(d.error){const fks=await db`select c.conrelid::regclass::text t,a.attname col from pg_constraint c join pg_attribute a on a.attrelid=c.conrelid and a.attnum=any(c.conkey) where c.confrelid='auth.users'::regclass and c.contype='f' and c.connamespace='public'::regnamespace`;
  for(const f of fks){const[{n}]=await db.unsafe(`select count(*)::int n from ${f.t} where "${f.col}"=$1`,[noWs.id]);if(n)console.log(' ref',f.t,f.col,n)}}}
await db.end({timeout:2});
