2	
3	import { cookies } from "next/headers";
4	import { revalidatePath } from "next/cache";
5	import { redirect } from "next/navigation";
6	import { z } from "zod";
7	import { APICallError, generateText } from "ai";
8	import { requireWorkspace } from "@/lib/auth";
9	import { AI_AGENT_KEYS, settingsSchema } from "@/lib/settings";
10	import { modelForSettings } from "@/lib/ai/provider";
11	import { minorDigits } from "@/lib/finance/fx";
12	import { revokeBankSessions } from "@/lib/bank/server";
13	
14	export async function saveSettings(_previous: { error?: string; saved?: boolean }, form: FormData): Promise<{ error?: string; saved?: boolean }> {
15	  try {
16	    const { supabase, workspace, settings: previous } = await requireWorkspace();
17	    const settings = settingsSchema.parse({
18	      timezone: form.get("timezone"), locale: form.get("locale"), theme: form.get("theme"), voice: form.get("voice"),
19	      ai_models: Object.fromEntries(AI_AGENT_KEYS.map(agent => [agent, String(form.get(`model:${agent}`) ?? "").trim()]).filter(([, model]) => model)),
20	      ai_data_scopes: form.getAll("ai_data_scopes"), muted_insight_types: form.getAll("muted_insight_types"),
21	      summary_cadence: form.get("summary_cadence"), summary_time: form.get("summary_time"),
22	    });
23	    const currency = z.string().regex(/^[A-Z]{3}$/, "Use a three-letter currency code").parse(form.get("display_currency"));
24	    minorDigits(currency);
25	    // Typed models are free text, so each newly changed one must answer before it is saved.
26	    for (const agent of AI_AGENT_KEYS) {
27	      if (!settings.ai_models[agent] || settings.ai_models[agent] === previous?.ai_models[agent]) continue;
28	      const check = await generateText({ model: await modelForSettings(settings, agent), prompt: "Reply with the single word OK.",
29	        maxOutputTokens: 512, maxRetries: 0, abortSignal: AbortSignal.timeout(15000) })
30	        .catch(error => APICallError.isInstance(error) && error.statusCode === 429 ? "rate-limited" as const : null);
31	      // A rate-limited model exists and answers later; only a missing or silent one blocks saving.
32	      if (check === "rate-limited") continue;
33	      if (!check?.text.trim()) throw new Error(`Model "${settings.ai_models[agent]}" did not respond; check the name and its API key`);
34	    }
35	    const result = await supabase.rpc("save_workspace_preferences", { p_workspace_id: workspace.id, p_display_currency: currency, p_preferences: settings });
36	    if (result.error) throw new Error("Preferences could not be saved; your previous settings are preserved");
37	    (await cookies()).set("moneo-theme", settings.theme, { httpOnly: true, sameSite: "lax", path: "/", maxAge: 31536000 });
38	    revalidatePath("/", "layout");
39	    return { saved: true };
40	  } catch (error) {
41	    return { error: error instanceof z.ZodError ? error.issues.map(issue => issue.message).join(". ") : error instanceof Error ? error.message : "Preferences could not be saved" };
42	  }
43	}
44	
45	export async function resetAllData(_previous: { error?: string }, form: FormData): Promise<{ error?: string }> {
46	  try {
47	    const { supabase, workspace } = await requireWorkspace();
48	    if (!z.literal("RESET").safeParse(form.get("confirmation")).success) return { error: "Type RESET to confirm" };
49	    // Storage RLS is keyed to the current workspace folder, so files go first while it is still ours.
50	    // ponytail: a failed reset after this leaves rows pointing at removed files; retrying the reset clears them.
51	    for (const bucket of ["imports", "chat"]) {
52	      for (;;) {
53	        const listed = await supabase.storage.from(bucket).list(workspace.id, { limit: 1000 });
54	        if (listed.error) throw listed.error;
55	        if (!listed.data.length) break;
56	        const removed = await supabase.storage.from(bucket).remove(listed.data.map(file => `${workspace.id}/${file.name}`));
57	        if (removed.error) throw removed.error;
58	        if (!removed.data.length) break; // RLS-denied removes return nothing; never spin
59	      }
60	    }
61	    await revokeBankSessions(workspace.id);
62	    const result = await supabase.rpc("reset_workspace");
63	    if (result.error) throw result.error;
64	  } catch {
65	    return { error: "Your data could not be reset. Try again." };
66	  }
67	  revalidatePath("/", "layout");
68	  redirect("/");
69	}
