26	  delete from public.financial_evidence_receipts where workspace_id=ws;
27	  delete from public.transaction_views where workspace_id=ws;
28	  delete from public.fx_rates where workspace_id=ws;
29	  delete from public.workspace_settings where workspace_id=ws;
30	
31	  -- Everything that points at transactions.
32	  delete from public.transaction_link_fees where workspace_id=ws;
33	  delete from public.transaction_links where workspace_id=ws;
34	  delete from public.transaction_splits where workspace_id=ws;
