54	  /** Widget positions relative to the grid, so the next change can animate from them. */
55	  function measure() {
56	    const origin = grid.current?.getBoundingClientRect();
57	    if (!origin) return [];
58	    return [...grid.current!.querySelectorAll<HTMLElement>(":scope > [data-widget]")].map(node => {
